/************************************ 锟斤拷锟矫猴拷锟斤拷************************************/
void mppt_mode(float Vpv, float Ppv, float dV, float dP){
	if(s_MPPf){            //return to previous MPP
		s_Vref = s_Vmpp;
		s_MPPf = 0;
		return;
	} else {s_Vref = s_Vrefprev;}
	if(!s_Pprev){return;}  //wait for power measurement

	//MAIN P&O Logic
	if(Ppv > s_Pprev){
		if(s_MPPT_dir){
			s_Vref = s_Vrefprev + s_deltaVref;
		}
		else {
			s_Vref = s_Vrefprev - s_deltaVref;
		}
	} else {
		if(s_MPPT_dir){
			s_Vref = s_Vrefprev - s_deltaVref;
			s_MPPT_dir = 0;
		}
		else {
			s_Vref = s_Vrefprev + s_deltaVref;
			s_MPPT_dir = 1;
		}
	}

	//Check for max power
	float PVslope = mwabs(dP/dV);
	if(PVslope < MPP_SLOPE){
		s_Pmax = Ppv;
		s_Vmpp = Vpv;
		s_MPPf = 1;
		s_mode = 1;
		s_Vref = s_Vrefprev;
		if(Ppv < s_Preserve*(2*LOW_IRR_FRAC)){  //if low irradiance,  stay in MPPT
			s_MPPf = 0;
			s_mode = 0;
		}
	}
}

void prc_measure_mode(float Vpv, float Ppv, float dV, float dP){
	if(s_Vpvmpre && !s_standby){ //return to last known point
		s_Vref = s_Vpvmpre;
		s_Vpvmpre = 0.0f;
		return;
	}
	// bool sameDir = (dV > dV_THRESH && dP>= -dP_THRESH) || (dV < -dV_THRESH && dP <= dP_THRESH);
	// bool notPmax = mwabs(s_Pmax - Ppv)/s_Preserve > PMAX_FRAC; 
	if ((Ppv < s_Preserve*LOW_IRR_FRAC)) {//|| (sameDir && notPmax)){ //low irradiance check & rapid irradiance check
		s_Vpvmpre = 0.0f;
		s_standby = 0;
		s_mode = 0;
		return;
	}
    if(mwabs(Ppv - s_Ppvmpre) > RESAMPLE_THRESH){ //prevent mode 0-1 oscillation
		s_standby2 = 0;
	}

	//search for reserve power
	float target = s_Pmax - s_Preserve;
	updateDeltaVprc(Ppv);
	if(Vpv < s_Vmpp){
		s_Vref = RECOVER_FRAC*s_Vmpp;
		return;}
	else {s_Vref = s_Vrefprev + s_deltaVprc;}
	// else if(Ppv > target){
	// 	s_Vref = s_Vrefprev + s_deltaVprc;
	// }
	// else if(Ppv < target){
	// 	s_Vref = s_Vrefprev - s_deltaVprc;
	// }

	bool onTarget = mwabs(Ppv - target) <= RP_THRESH;
	test_float = min_abs_diff(Ppv,s_Ppva,s_k);
	bool noRepeatP = test_float >= REPEAT_THRESH_P;
	bool rightSide = Vpv > s_Vmpp;

	if(s_fine && onTarget && !s_standby){
		s_Vpvmpre = Vpv;
		s_standby = 1;
		if(onTarget && rightSide && noRepeatP){
			int idxR = insertPoint(Vpv,Ppv);
			if(s_k >= MIN_IDX && !s_sortFail){
				s_mode = 2;
				s_standby = 0;
				s_standby2 = 0;
			} else if(s_sortFail != 0){
				s_test += 1;
				if(s_k ==1){
					s_Vpva[0] = Vpv;
					s_Ppva[0] = Ppv;
				}else{
					int i = idxR;
					for( i =idxR; i<(s_k); i++){  //remove point causing sortfail
						s_Vpva[i] = s_Vpva[i+1];
						s_Ppva[i] = s_Ppva[i+1];
					}
					s_k -= 1;
				}
				s_sortFail = 0;
				s_mode = 0;
				s_standby = 0;
				s_standby2 = 0;
			}
		}
		s_fine = 0;
	}

	// Exit conditions
	if(s_standby && !s_standby2 && s_k>=MIN_IDX && Ppv < s_Ppva[s_k-1] && Ppv > s_Ppva[0]){
		s_mode = 2;
		s_standby = 0;
		s_standby2 = 0;
	} else if(s_standby && noRepeatP && !s_standby2){
		s_mode = 0;
		s_standby = 0;
		s_standby2 = 1;
		s_Ppvmpre = Ppv;
	}
}

float min_abs_diff(float value, const float* array, int array_size) {
    if (!array_size) {return value;}
    
    float min_diff = mwabs(value - array[0]);
    int i = 1;
    for (i = 1; i < array_size; i++) {
        float diff = mwabs(value - array[i]);
        if (diff < min_diff) {min_diff = diff;}
    }
    
    return min_diff;
}

void updateDeltaVprc(float Ppv){
	// s_err = mwabs(Ppv - (s_Pmax - s_Preserve));
	s_err = Ppv - (s_Pmax - s_Preserve);
	s_errInt += s_err;
	//controller to search for PRC point
	float Kp = 1/34.0; //23 for 600, 34 for 1000
	s_deltaVprc = Kp*s_err;

	if(mwabs(s_err/(s_Pmax- s_Preserve)) < 0.025){s_fine = 1;}

	// lookup table method to search for PRC point
	// if(s_err >= 1000.0f){s_deltaVprc = 15.0f;}
	// else if(s_err>= 500.0f){s_deltaVprc = 10.0f;}
	// else if(s_err>= 200.0f){s_deltaVprc = 5.0f;}
	// else if(s_err>= 100.0f){s_deltaVprc = 2.5f;}
	// else if(s_err > 50.0f){s_deltaVprc = 1.0f;}
	// else if(s_err <= 50.0f){
	// 	s_deltaVprc = 0.25f;
	// 	s_fine = 1;
	// }

	if(s_standby){s_deltaVprc = 0.0f;}
	
}

int insertPoint(float Vpv, float Ppv){
	int idxP = s_k;
	int idxV = s_k;
	int idxR = 0;
	int i = 0;
	for(i=0; i<(s_k); i++){
		if(Ppv < s_Ppva[i]){ //ascending
			idxP = i;
			break;
		}
	}
	for(i=0; i<(s_k); i++){
		if(Vpv < s_Vpva[i]){ //ascending
			idxV = i;
			break;
		}
	}

	if(idxP != idxV){
		s_sortFail = 1;
		idxR = idxV; //remove the voltage on failure
		return idxR;
	}

	if(s_k){
		for(i = (s_k-1); i >= idxP; i--){
			s_Ppva[i+1] = s_Ppva[i];
			s_Vpva[i+1] = s_Vpva[i];
		}
	}

	s_Ppva[idxP] = Ppv;
	s_Vpva[idxV] = Vpv;
	s_k += 1;
	s_sortFail = 0;
	return idxR;
}

void prc_operate_mode(float Vpv, float Ppv){
	int idx[3];
	if(Ppv < s_Ppva[2] || s_k == MIN_IDX){
		idx[0] = 0;
		idx[1] = 1;
		idx[2] = 2;
	}else if(Ppv > s_Ppva[s_k-2]){
		idx[0] = s_k - 3;
		idx[1] = s_k - 2;
		idx[2] = s_k - 1;
	}else{
		int minIdx = 1;
		float minDiff = mwabs(Ppv - s_Ppva[minIdx]);
		int i =1;
		for(i=1;i<(s_k-1);i++){
			if(mwabs(Ppv - s_Ppva[i]) < minDiff){ 
				minDiff = mwabs(Ppv - s_Ppva[i]);
				minIdx = i;   //search for the smallest difference among sample points
			}
		}
		idx[0] = minIdx - 1;
		idx[1] = minIdx;     //center bracket around that point
		idx[2] = minIdx + 1;
	}

	//get all the curve fit points
	s_Vpm[0] = s_Vpva[idx[0]];
	s_Vpm[1] = s_Vpva[idx[1]];
	s_Vpm[2] = s_Vpva[idx[2]];
	s_Ppm[0] = s_Ppva[idx[0]];
	s_Ppm[1] = s_Ppva[idx[1]];
	s_Ppm[2] = s_Ppva[idx[2]];

	
	double dV21 = (double) (s_Vpm[1] - s_Vpm[0]);
	double dV32 = (double) (s_Vpm[2] - s_Vpm[1]);
	double dV13 = (double) (s_Vpm[0] - s_Vpm[2]);
	double dP21 = (double) (s_Ppm[1] - s_Ppm[0]);
	double dP32 = (double) (s_Ppm[2] - s_Ppm[1]);
	double P0 = (double) s_Ppm[0];
	double V0 = (double) s_Vpm[0];

	s_A = (dP21*dV32 - dP32*dV21) / (dV21 * dV32 * dV13);
	s_B = (dP21 - s_A*(s_Vpm[1]*s_Vpm[1] - s_Vpm[0]*s_Vpm[0])) / dV21;
	s_C  = P0 - s_A*V0*V0 - s_B*V0;
	
	double Vpvd = (double) Vpv;
	double Pcurve = (s_A*Vpvd*Vpvd + s_B*Vpvd + s_C);
	double Vcrit = -s_B/(2*s_A);
	double Pcrit = s_A*Vcrit*Vcrit + s_B*Vcrit +s_C;

	bool fallOff = (s_A < 0 && (double)Ppv > Pcrit) || (s_A > 0 && (double)Ppv < Pcrit);
	int idxR = -1;
	if(fallOff){
		if(s_A < 0){idxR = s_k - 1;}
		else{idxR = 0;}
		int i = idxR;
		for( i =idxR; i<(s_k); i++){  //remove point causing sortfail
			s_Vpva[i] = s_Vpva[i+1];
			s_Ppva[i] = s_Ppva[i+1];
		}
		s_k -= 1;
	}

	if( (double)Ppv <= Pcurve){
		s_Vref = s_Vrefprev - DELTA_CURVE;
	} else {
		s_Vref = s_Vrefprev + DELTA_CURVE;
	}

	bool lowIrr = Ppv < s_Preserve*LOW_IRR_FRAC;

	// exit conditions
	test_float = min_abs_diff(Ppv,s_Ppva,s_k);
	if(test_float >= NEW_POINT || fallOff || lowIrr || s_k < MIN_IDX){
		s_Vpvmpre = Vpv;
		s_mode = 0;
		s_standby2 = 0;
	}

}

 void lpf( float x, float *y, float b1, float a0 )
  {
   *y = b1 * *y + a0 * x;
  }
 void lpf2( float x, float *x_pre, float *y, float *y_pre, float b1, float b2, float a )
  {
     *y = a * ( b1* *y_pre + b2 * *(y_pre+1) + x + 2.0f * *x_pre + *(x_pre+1));
     *(x_pre+1) = *x_pre;
     *x_pre = x;
     *(y_pre+1) = *y_pre;
     *y_pre = *y;
  }
 void resonant( float x,float *x_pre1, float *x_pre2, float *y, float *y_pre1,float *y_pre2, float b1, float b2,  float a ,float max, float min)
  {
   *y = b1* *y_pre1 + b2 * *y_pre2 + a* ( x -  *x_pre2);
   if ( *y > max )  *y = max;
   else if ( *y < min )  *y = min;
   *x_pre2 = *x_pre1;
   *x_pre1 = x;
   *y_pre2 = *y_pre1;
   *y_pre1 = *y;
  }



