	l_ls1 = x1 * w50_reci - L_LINE1 - L_F1;						/* INV1锟斤拷锟斤拷锟斤拷锟斤拷[H] */
	I1=0; //test
  /****    AD锟斤拷Q    ****/
	data1[0]=0.0f, data1[1]=0.0f, data1[2]=0.0f, data1[3]=0.0f;
	data1[4]=0.0f, data1[5]=0.0f, data1[6]=0.0f, data1[7]=0.0f;	/* PEV0锟斤拷AD转锟斤拷锟斤拷锟捷讹拷取 */

