void mysvpwm( float r, float a, float *u, float *v, float *w)
 {
    float r_t, x, y, ra, rb, rc, d1, d2, d0_half;
    bool ab, bc, ca;

    r_t = r * 0.7071068f;                                       /* 锟斤拷詢x锟絅锟絞锟斤拷锟絯锟竭傦拷锟絆锟斤拷锟絯锟竭偵曄婏拷 */
    ra2xy( r_t, a, &x, &y );
    ab2uvw( x, y, &ra, &rb, &rc );

    ab = (ra >= rb);                                            /* 锟絆锟斤拷锟絯锟竭抣锟藉偒锟斤拷锟教忥拷锟皆偺妋锟紽 */
    bc = (rb >= rc);
    ca = (rc >= ra);

    if(ab)
    {
        if(bc)                                                  /* Section I (0 ~ 锟斤拷/3) */
        {
            d1 = 2.0f * ra + rc;
            d2 = -(ra + 2.0f * rc);
            d0_half = 0.5f * (1.0f - d1 - d2);
            *u = 2.0f * (d1 + d2 + d0_half) - 1.0f;
            *v = 2.0f * (d2 + d0_half) - 1.0f;
            *w = 2.0f * d0_half - 1.0f;
        }
        else if (ca)                                            /* Section V (4锟斤拷/3 ~ 5锟斤拷/3) */
        {
            d1 = 2.0f * rc + rb;
            d2 = -(rc + 2.0f * rb);
            d0_half = 0.5f * (1.0f - d1 - d2);
            *w = 2.0f * (d1 + d2 + d0_half) - 1.0f;
            *u = 2.0f * (d2 + d0_half) - 1.0f;
            *v = 2.0f * d0_half - 1.0f;
        }
        else                                                    /* Section VI (5锟斤拷/3 ~ 2锟斤拷) */
        {
            d1 = 2.0f * ra + rb;
            d2 = -(ra + 2.0f * rb);
            d0_half = 0.5f * (1.0f - d1 - d2);
            *u = 2.0f * (d1 + d2 + d0_half) - 1.0f;
            *w = 2.0f * (d2 + d0_half) - 1.0f;
            *v = 2.0f * d0_half - 1.0f;
        }
    }
    else
    {
        if(!ca)                                                 /* Section II (锟斤拷/3 ~ 2锟斤拷/3) */
        {
            d1 = 2.0f * rb + rc;
            d2 = -(rb + 2.0f * rc);
            d0_half = 0.5f * (1.0f - d1 - d2);
            *v = 2.0f * (d1 + d2 + d0_half) - 1.0f;
            *u = 2.0f * (d2 + d0_half) - 1.0f;
            *w = 2.0f * d0_half - 1.0f;
        }
        else if (!bc)                                           /* Section IV (锟斤拷 ~ 4锟斤拷/3) */
        {
            d1 = 2.0f * rc + ra;
            d2 = -(rc + 2.0f * ra);
            d0_half = 0.5f * (1.0f - d1 - d2);
            *w = 2.0f * (d1 + d2 + d0_half) - 1.0f;
            *v = 2.0f * (d2 + d0_half) - 1.0f;
            *u = 2.0f * d0_half - 1.0f;
        }
        else                                                    /* Section III (2锟斤拷/3 ~ 锟斤拷) */
        {
            d1 = 2.0f * rb + ra;
            d2 = -(rb + 2.0f * ra);
            d0_half = 0.5f * (1.0f - d1 - d2);
            *v = 2.0f * (d1 + d2 + d0_half) - 1.0f;
            *w = 2.0f * (d2 + d0_half) - 1.0f;
            *u = 2.0f * d0_half - 1.0f;
        }
    }
 }

